  'fitting': 'itinye',
  'Pick your phone and see every repair we do for it: the part in each grade, the fitting fee and the total, before you come in.': 'Họrọ ekwentị gị hụ nrụzi ọ bụla: akụkụ n’ọkwa ọ bụla, ụgwọ itinye na ngụkọta, tupu ị bịa.',
  'Every repair for the': 'Nrụzi niile maka',
  'Part price + fitting fee = your total. Prices are samples; the bench confirms the final price before starting.': 'Ọnụahịa akụkụ + ụgwọ itinye = ngụkọta gị. Ọnụahịa bụ ihe atụ; a na-akwado ọnụahịa ikpeazụ tupu mmalite.',
  'The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.': 'Ụgwọ na-eso ọnụahịa akụkụ. Onye ọrụ anyị nwere ike ịgbanwe ya, ọ na-agwakwa gị tupu ọ malite.',
  'Book this repair': 'Debe nrụzi a',
