  'This part of the site is still being built. Everything you need is on the home page in the meantime.': 'A ka na-ewu akụkụ saịtị a. Ka ọ dị ugbu a, ihe niile ị chọrọ dị na ibe mbụ.',
  'Open Find My Part': 'Mepee Chọta akụkụ m',
