  'Brand names & trademarks': 'Aha akara na akara azụmahịa',
  'Compatibility only': 'Naanị maka ndakọrịta',
  'Original and compatible parts': 'Akụkụ izizi na ndị dabara',
  'Four kinds, named after phone parts': 'Ụdị anọ, aha ha sitere n’akụkụ ekwentị',
  'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Contact: samelectronics.uae@gmail.com.': 'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Kpọtụrụ: samelectronics.uae@gmail.com.',
  'These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates ("Sam Electronics", "we"), in the shop, on this website, on WhatsApp or by phone.': 'Usoro ndị a metụtara ire ọ bụla nke Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates ("Sam Electronics", "anyị") na-eme, n’ụlọ ahịa, na weebụsaịtị a, na WhatsApp ma ọ bụ site na ekwentị.',
  'Prices, stock, delivery times and offers depend on where you are. Please do not hide your location (for example with a VPN) when you browse or order; if you do, what you see may not apply to you and we may ask you to confirm your location before we confirm an order.': 'Ọnụahịa, ngwaahịa dị, oge nnyefe na onyinye dabere n’ebe ị nọ. Biko ezoghị ebe ị nọ (dịka site na VPN) mgbe ị na-elele ma ọ bụ na-enye ọda; ọ bụrụ na i mee ya, ihe ị hụrụ nwere ike ọ gaghị emetụta gị, anyị nwekwara ike ịrịọ gị ka ị kwado ebe ị nọ tupu anyị akwado ọda.',
  'Everything on this website and in our systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by UAE copyright law (Federal Decree-Law No. 38 of 2021). You may keep a copy for your own reference; copying, sharing or publishing it needs our written permission.': 'Ihe niile dị na weebụsaịtị a na n’usoro anyị (foto, nhazi, ederede, ọnụahịa na data) bụ nke Sam Electronics, iwu nwebiisinka UAE (Iwu Federal Nọmba 38 nke 2021) na-echekwa ya. Ị nwere ike idowe otu nnomi maka onwe gị; idegharị, ịkesa ma ọ bụ ibipụta ya chọrọ ikike anyị e dere ede.',
  'Account details (name, e-mail, phone, password stored encrypted), company details you add, orders and invoices, messages you send us, Samsoom chats if you keep them with your account, and basic technical data (device, pages visited) to keep the site working.': 'Nkọwa akaụntụ (aha, ozi-e, ekwentị, okwuntughe echekwara n’ezoghị ezo), nkọwa ụlọ ọrụ ị tinyere, ọda na akwụkwọ ụgwọ, ozi ị zitere anyị, mkparịta ụka Samsoom ma ọ bụrụ na i debe ha n’akaụntụ gị, na data teknụzụ ndabere (ngwaọrụ, ibe ndị a gara) ka saịtị wee rụọ ọrụ.',
  'Ask for a copy, a correction or deletion of your data, or object to its use, using the privacy form on the contact page. We answer within 30 days, in line with the UAE personal data protection law.': 'Rịọ maka nnomi, mgbazi ma ọ bụ ihichapụ data gị, ma ọ bụ kwụsị iji ya, site na fọm nzuzo dị na ibe kọntaktị. Anyị na-aza n’ime ụbọchị 30, dịka iwu UAE na-echebe data onwe si dị.',
  'Battery (essential, always on): your cart, language, sign-in and these choices. Kept until you clear them; sign-in until you sign out.': 'Batrị (dị mkpa, na-agbanye mgbe niile): ụgbọ ahịa gị, asụsụ, mbanye na nhọrọ ndị a. A na-edowe ha ruo mgbe i hichapụrụ ha; mbanye ruo mgbe ị pụrụ.',
  'Memory Chip (preferences): currency, sounds, recent searches, starred parts and your devices. Kept 12 months.': 'Mgbawa ebe nchekwa (mmasị): ego, ụda, nchọ ndị na-adịbeghị anya, akụkụ nwere kpakpando na ngwaọrụ gị. A na-edowe ọnwa 12.',
  'Diagnostics (anonymous statistics): which pages are opened and how fast they load, never your name or contact. Kept 13 months.': 'Nchọpụta (ọnụọgụgụ na-enweghị aha): ibe ndị a na-emeghe na ọsọ ha si ebu, ọ dịghị mgbe aha gị ma ọ bụ kọntaktị gị. A na-edowe ọnwa 13.',
  'Antenna (marketing and offers): the kinds of parts you look at, to show matching offers. Kept 6 months.': 'Antenna (ahịa na onyinye): ụdị akụkụ ị na-ele, iji gosi onyinye dabara. A na-edowe ọnwa 6.',
  'The banner asks once, after the welcome. Change your choice any time with "Cookie settings" at the bottom of every page, or clear everything in your browser: the site will simply forget your cart and preferences on that device. Each choice is saved with its date.': 'Bana ahụ na-ajụ otu ugboro, mgbe nnabata gasịrị. Gbanwee nhọrọ gị mgbe ọ bụla site na "Ntọala kuki" n’okpuru ibe ọ bụla, ma ọ bụ hichapụ ihe niile na ihe nchọgharị gị: saịtị ga-echefu ụgbọ ahịa gị na mmasị gị na ngwaọrụ ahụ. A na-echekwa nhọrọ ọ bụla na ụbọchị ya.',
  'Brand names, model names and logos (such as Apple, Samsung, Xiaomi, Huawei and others) belong to their owners. We use them only to show which phones a part fits. Sam Electronics is an independent parts seller and repair shop, and is not affiliated with, authorised by or endorsed by these brands unless a page says so.': 'Aha akara, aha ụdị na akara ngosi (dịka Apple, Samsung, Xiaomi, Huawei na ndị ọzọ) bụ nke ndị nwe ha. Anyị na-eji ha naanị iji gosi ekwentị akụkụ dabara. Sam Electronics bụ onye na-ere akụkụ na ụlọ ndozi nọọrọ onwe ya, enweghị njikọ, ikike ma ọ bụ nkwado site n’aka akara ndị a belụsọ ma ibe kwuru otú ahụ.',
  'Every part is labelled with its quality and its maker. "Original" and "Service Pack" mean parts made for the brand; every other quality is a compatible part from the maker named on the label.': 'Akụkụ ọ bụla nwere akara ogo ya na onye mere ya. "Original" na "Service Pack" pụtara akụkụ e mere maka akara ahụ; ogo ọ bụla ọzọ bụ akụkụ dabara nke onye mmepụta akpọrọ aha na akara.',
  'LIVE PARTS BOARD · LIVE FEED': 'BỌỌDỤ AKỤKỤ NDỤ · NDỤ',
  'REPAIR SHOP': 'ỤLỌ NDOZI',
  'A54 OLED SCREEN': 'IHUENYO OLED A54',
