  'Register online, your first purchase activates it.': 'Debanye aha n’ịntanetị, ịzụ ahịa mbụ gị na-eme ka ọ rụọ ọrụ.',
  'For shops and traders': 'Maka ụlọ ahịa na ndị ahịa',
  'Apply with your trade licence; we activate it by hand.': 'Tinye akwụkwọ ikike azụmahịa gị; anyị na-eme ka ọ rụọ ọrụ n’aka.',
