  'Read every working day': 'A na-agụ ya ụbọchị ọrụ ọ bụla',
  'We reply by e-mail, usually the same day.': 'Anyị na-aza site na ozi-e, ọtụtụ mgbe n’otu ụbọchị.',
  'Walk in, no appointment': 'Bata, enweghị ọkwa',
  'Team online': 'Otu nọ n’ịntanetị',
