  'Line open': 'Ahịrị mepere',
  'Line closed': 'Ahịrị mechiri',
  'Leave a message': 'Hapụ ozi',
  'Batteries, flex cables, small parts': 'Batrị, waya flex, obere akụkụ',
  'Most screens, cameras, back glass': 'Ọtụtụ ihuenyo, igwefoto, iko azụ',
  'Original screens on flagship phones': 'Ihuenyo izizi na ekwentị kacha elu',
  'Tell us when, we print your job card.': 'Gwa anyị mgbe, anyị ga-ebipụta kaadị ọrụ gị.',
  'SHIPPING ORDER': 'ỌDA MBUPU',
  'Tap “Model Number” once: it changes to a code that starts with A (for example A2846).': 'Pịa "Nọmba ụdị" otu ugboro: ọ ga-agbanwe ghọọ koodu na-amalite na A (dịka A2846).',
  'Parts, repairs, trade, shipping and payments. Search, or pick a topic. Still stuck? Samsoom is one tap away.': 'Akụkụ, ndozi, azụmahịa, mbupu na ịkwụ ụgwọ. Chọọ ma ọ bụ họrọ isiokwu. Ka nwere nsogbu? Samsoom dị otu mpịa.',
  'Pay your way.': 'Kwụọ ụgwọ n’ụzọ gị.',
  'Every way you can pay us today, in the shop, online and from abroad. Prices are in AED; card payments are charged in AED.': 'Ụzọ niile ị ga-esi kwụọ anyị taa, n’ụlọ ahịa, n’ịntanetị na site ná mba ofesi. Ọnụahịa dị na AED; a na-ana ụgwọ kaadị na AED.',
  'Online card payments go through a secure payment page; we never see or keep your card details.': 'Ịkwụ ụgwọ kaadị n’ịntanetị na-esi n’ibe nchekwa; anyị anaghị ahụ ma ọ bụ edobe nkọwa kaadị gị.',
  'We never ask for your card number on WhatsApp or by e-mail.': 'Anyị anaghị arịọ nọmba kaadị gị na WhatsApp ma ọ bụ ozi-e.',
  'Need another way to pay? Ask us on WhatsApp and we will tell you what is possible.': 'Ịchọrọ ụzọ ọzọ ịkwụ ụgwọ? Jụọ anyị na WhatsApp, anyị ga-agwa gị ihe ga-ekwe omume.',
  'When your internet connection says you are in a different place than your device’s clock, you are most likely using a VPN or a proxy.': 'Mgbe njikọ ịntanetị gị gosiri ebe dị iche na elekere ngwaọrụ gị, o yikarịrị ka ị na-eji VPN ma ọ bụ proxy.',
  'Prices, stock, delivery times and offers on this website depend on where you really are. With a hidden location, what you see may not apply to you, and we may ask you to confirm your location before we confirm an order.': 'Ọnụahịa, ngwaahịa, oge nnyefe na onyinye na weebụsaịtị a dabere n’ebe ị nọ n’ezie. Ọ bụrụ na e zoro ebe ị nọ, ihe ị hụrụ nwere ike ọ gaghị emetụta gị, anyị nwekwara ike ịrịọ gị ka ị kwado ya tupu anyị akwado ọda.',
  'Our terms of use ask visitors not to hide their location when browsing or ordering. If you are simply travelling, choose “I am travelling” and carry on: nothing else changes.': 'Usoro ojiji anyị na-arịọ ndị ọbịa ka ha ghara izo ebe ha nọ mgbe ha na-elele ma ọ bụ na-enye ọda. Ọ bụrụ na ị na-eme njem, họrọ "Ana m eme njem" ma gaa n’ihu: ọ nweghị ihe ọzọ na-agbanwe.',
  'We only compare two time zones. We never store your IP address.': 'Anyị na-atụnyere naanị mpaghara oge abụọ. Anyị anaghị edobe adreesị IP gị.',
  'Browsers can only see the screenshot keys on computers (Print Screen, ⌘⇧3/4/5, Win+Shift+S). When we see one, this notice appears once and the team is told which page it was.': 'Ihe nchọgharị na-ahụ igodo nseta ihuenyo naanị na kọmputa (Print Screen, ⌘⇧3/4/5, Win+Shift+S). Mgbe anyị hụrụ otu, ọkwa a na-apụta otu ugboro, a na-agwakwa otu ibe ọ bụ.',
  'If you took it for another reason, you can safely ignore the notice. For permission, write to us from the Contact page.': 'Ọ bụrụ na i were ya maka ihe ọzọ, ị nwere ike ileghara ọkwa ahụ anya. Maka ikike, degara anyị site n’ibe kọntaktị.',
