  'Shop commercial: screens, every grade, battery week, trade prices, worldwide shipping.': 'Mgbasa ozi ụlọ ahịa: ihuenyo, ogo ọ bụla, izu batrị, ọnụahịa ndị ahịa, mbupu n’ụwa niile.',
  'The big box plays our latest offers. Pick a tab, a part or a brand and it shows that topic\'s own deals.': 'Igbe ukwu na-egosi onyinye anyị ọhụrụ. Họrọ taabụ, akụkụ ma ọ bụ aha ka ọ gosi onyinye ya.',
  'The coloured tag is the quality (Original, OLED, Incell, AAA and more). The dark tag with a light is who made it.': 'Akara nwere agba bụ ogo (Original, OLED, Incell, AAA na ndị ọzọ). Akara gbara ọchịchịrị nwere ìhè bụ onye mere ya.',
  'Star a part to keep it in My Bench. The two-cards button adds it to Compare: up to three parts side by side.': 'Tinye kpakpando ka idobe ya na My Bench. Bọtịnụ kaadị abụọ na-etinye ya na Tụnyere: ruo akụkụ atọ.',
  'Sort by price, newest or best match, and switch between the grid and the list.': 'Hazie site n’ọnụahịa, nke ọhụrụ ma ọ bụ nke kacha dabara, ma gbanwee n’etiti grid na ndepụta.',
  'Repair shops and traders: apply once, and every part shows your trade price.': 'Ụlọ nrụzi na ndị ahịa: tinye akwụkwọ otu ugboro, akụkụ ọ bụla ga-egosi ọnụahịa gị.',
  'The questions people ask most, answered in one place. Still stuck? Ask Samsoom.': 'Ajụjụ ndị mmadụ na-ajụkarị, n’otu ebe. Ka nwere nsogbu? Jụọ Samsoom.',
